import * as Rights from "approot/global/references/rights.js";

const nodeType = {
	plan: "plan",
	unit: "unit",
	lesson: "lesson"
}

class PlannerCtrl {
	constructor(options) {
		var defOptions = {
			container: null,
			readOnly: false,
			immediatelyLoad: true,
			ctx: null
		};

		this.options = $.extend({}, defOptions, options);
		this.planTree = null;
		this.ctx = options.ctx;
		if(!appContext.hasAnyRight([Rights.arCurrMgmCreateAll, Rights.arCurrMgmCreate])) {
			this.options.readOnly = true;
		}
		this.planNoteRow = $("#plan-note-row");
	}

	getPlan() {
		var planId = this.ctx.planId;
		if (planId) {
			return _.findWhere(this.planTree, { key: planId });
		}
		return null;
	}

	processButtons() {
		const emptyPlan = this.planTree.length === 0;

		if (emptyPlan) {
			//если план пуст - прячем все кнопки кроме "Варианты"
			$(".action-panel").find("button").addClass("hide");
			$("#variants-btn").removeClass("hide");
		} else {
			//иначе показываем все
			$(".action-panel").find("button").removeClass("hide");
		}

		if (this.options.readOnly) {
			$("#copy-btn").addClass("hide");
			$("#variants-btn").addClass("hide");
		}

		if (emptyPlan) {
			return;
		}

		if (this.ctx.readOnly || this.options.readOnly) {
			$(".btn-write-access").addClass("hide");
			$(".btn-readonly-access").removeClass("hide");
		}
		else {
			$(".btn-write-access").removeClass("hide");
			$(".btn-readonly-access").addClass("hide");
		}
	}

	init() {
		this.attachEvents();
		this.initTree();

		jsSubmit({
			action: "/webapi/subjectplans/filter",
			method: "GET",
			showProcessing: true
		}).then((response) => {
			var model = response.filterPanel;
			var sources = response.filterSources;

			const fpContainer = $(".filters-panel");
			this.fp = new filterPanel(fpContainer, model, sources, "/webapi/subjectplans/filter/init");

			this.planNoteRow = $("<div class=\"form-group\" id=\"plan-note-row\"><label class=\"control-label\">Пояснительная записка</label><div><div id=\"attachFiles\" style='max-width: 500px'></div></div></div>");
			this.planNoteRow.insertAfter(fpContainer.find(".form-group:last"));

			if (this.ctx.elementType != "pl") {
				this.planNoteRow.hide();
			}

			this.fp.emptyChoice(() => {
				$("#load-plan-btn").attr("disabled", "disabled");
			});

			this.fp.ready(() => {
				$("#load-plan-btn").removeAttr("disabled");
			});

			if (this.options.immediatelyLoad) {
				this.load();
			}
		});
	}

	load(extFilter) {

		const fpVals = this.fp.getValues();
		const fpFilter = { yearId: appContext.yearId, subjectId: fpVals.SBJID, grade: fpVals.GRADEID, variantId: fpVals.VARIANTID || -1 };
		const filter = $.extend({}, fpFilter, extFilter);


		const initNodeTypes = (treeModel) => {

			let activated = false;
			_.each(treeModel, (plan) => {
				plan.nodeType = nodeType.plan;
				if (this.ctx.elementType === "pl" && this.ctx.elementId == plan.key) {
					plan.activate = true;
					plan.focus = true;
					activated = true;
					this.ctx.readOnly = plan.readOnly || false;
				}

				if (!plan.children) {
					return;
				}
					
				_.each(plan.children, (unit) => {
					unit.nodeType = nodeType.unit;
					if (this.ctx.elementType === "un" && this.ctx.elementId == unit.key) {
						unit.activate = true;
						unit.focus = true;
						activated = true;
						this.ctx.readOnly = plan.readOnly || false;
					}

					if (!unit.children) {
						return;
					}

					_.each(unit.children, (lesson) => {
						lesson.nodeType = nodeType.lesson;
						if (this.ctx.elementType === "ls" && this.ctx.elementId == lesson.key) {
							lesson.activate = true;
							lesson.focus = true;
							activated = true;
							this.ctx.readOnly = plan.readOnly || false;
						}
					});
				});
			});

			if (!activated) {
				//сброс контекста выбора
				this.ctx.elementType = null;
			}
			return treeModel;
		};

		const setTreeData = (treeModel) => {
			this.planTree = treeModel;

			var rootNode = $(this.options.container).dynatree("getRoot");

			rootNode.removeChildren();
			rootNode.addChild(this.planTree);

			this.initPlanAttachments();

			this.processButtons();
		}

		jsSubmit({
			method: "GET",
			action: "/webapi/subjectplans/tree",
			data: filter,
			rawSettings: {
				withCredentials: true
			}
		})
		.then(initNodeTypes)
		.then(setTreeData)
		.then(() => {
			if (!this.planTree.length) {
				$("#empty-plan-panel").removeClass("hide");
				$("#plan-container").addClass("hide");
			} else {
				$("#plan-container").removeClass("hide");
				$("#empty-plan-panel").addClass("hide");
			}
			$(".action-panel").removeClass("hide");
			var node = $("#tree").dynatree("getTree").getActiveNode();
			if (!node) {
				return;
			}
			const nodeTopOffset = $(node.li).offset().top;
			const clientHeight = document.documentElement.clientHeight;
			if (clientHeight > nodeTopOffset + 10) {
				//элемент на странице виден - скролл не требуется
				return;
			}

			const scrollSize = nodeTopOffset - clientHeight + 100;
			$('html, body').animate({ scrollTop: scrollSize }, 20);
		});
	}

	//инциализация файловых вложений
	initPlanAttachments() {
		var plan = this.getPlan();

		if (!plan) {
			this.planNoteRow.hide();
			return;
		}

		const readOnly = this.options.readOnly || plan.readOnly || false;
		const block = $('#attachFiles');

		const faSettings = {
			multiple: false,
			showDescription: true,
			readonly: readOnly,
			onSuccessAttach: (file) => {
				//добавляем файл в "дерево"
				plan.attach = {
					id: file.Id,
					originalFileName: file.Name,
					description: file.Description
				};
			},
			onSuccessDetach: () => plan.attach = null,
			block: block
		};

		const data = {
			wasChanged: false,
			context: {
				PlanId: plan.key
			}
		};

		if (plan.attach) {
			block.closest(".form-group").show();
			const file = {
				FileAttachmentId: plan.attach.id,
				FileName: plan.attach.originalFileName,
				Description: plan.attach.description
			};
			data.files = [file];
		}

		//todo избавиться от глобального контекста
		window.fileAttachmentCtrl = new FileAttachmentCtrl(faSettings, data);
		this.planNoteRow.show();
		if (!plan.attach && readOnly) {
			this.planNoteRow.hide();
		}
	}

	//инициализации дерева
	initTree() {
		const cookiePersist = (flag, node) => {
			//сохраняем состояние в куках
			var expandInfo = $.cookie(`PL_EXP_${node.data.nodeType}`) || "";
			var expandNodes = expandInfo.split("|");
			if (flag) {
				expandNodes.push(node.data.key);
			} else {
				expandNodes = _.without(expandNodes, node.data.key);
			}
			expandInfo = expandNodes.join("|");
			$.cookie(`PL_EXP_${node.data.nodeType}`, expandInfo, { path: "/" });
		};

		$(this.options.container).dynatree({
			title: "КТП",
			fx: { height: "toggle", duration: 200 },
			autoFocus: false,
			onExpand: cookiePersist,
			onQueryExpand: cookiePersist,
			onActivate: (node) => {
				if (node.data.nodeType === nodeType.plan) {
					this.ctx.elementType = "pl";
					this.ctx.planId = node.data.key;
					this.ctx.unitId = null;
					this.ctx.lessonId = null;

					this.initPlanAttachments();
				}
				else if (node.data.nodeType === nodeType.unit) {
					this.ctx.elementType = "un";
					this.ctx.unitId = node.data.key;
					this.ctx.planId = node.parent.data.key;
					this.ctx.lessonId = null;

					this.planNoteRow.hide();
				}
				else if (node.data.nodeType === nodeType.lesson) {
					this.ctx.elementType = "ls";
					this.ctx.lessonId = node.data.key;
					this.ctx.unitId = node.parent.data.key;
					this.ctx.planId = node.parent.parent.data.key;

					this.planNoteRow.hide();
				}
				this.ctx.currElementName = node.data.title;
				this.ctx.elementId = node.data.key;
				this.ctx.readOnly = true;

				let plan = this.getPlan() || {};
				this.ctx.readOnly = plan.readOnly || false;

				this.processButtons();
			},
			onLazyRead: function (node) {
				var action = "";
				const data = {};
				var loadNodeType = "";
				if (node.data.nodeType === nodeType.plan) {
					action = "/webapi/subjectplans/tree/units";
					data.planId = node.data.key;
					loadNodeType = "unit";
				}
				else if (node.data.nodeType === nodeType.unit) {
					action = "/webapi/subjectplans/tree/lessons";
					data.unitId = node.data.key;
					loadNodeType = "lesson";
				}

				jsSubmit({
					method: "GET",
					action: action,
					data: data
				}).then( (response) => {

					var items = response;
					if (items.length) {
						_.each(items, function (item) { item.nodeType = loadNodeType; });
						node.addChild(items);
					}
					else {
						node.data.isFolder = false;
					}

				});
			}
		});
	}

	attachEvents() {
		$("#edit-btn").click(() => {
			this.editItem();
		});

		$("#copy-btn").click(() => {
			this.copyItem();
		});

		$("#view-btn").click(() => {
			this.editItem();
		});

		$("#create-btn").click(() => {
			this.createItem();
		});

		$("#del-btn").click(() => {
			this.deleteItem();
		});

		$("#import-btn").click(() => {
			this.importKTP();
		});

		$("#export-btn").click(() => {
			this.exportKTP();
		});

		$("#load-plan-btn").click(() => {
			this.load();
		});

		$("#expand-btn").click(() => {
			this.expandAll();
		});

		$("#collapse-btn").click(() => {
			this.collapseAll();
		});

		$("#report-btn").click(() => {
			this.openReport();
		});

		$("#variants-btn").click(() => {
			this.goVariants();
		});
	}


	editItem() {
		if (this.ctx.elementType == "un") {
			this.editUnit();
		}
		else if (this.ctx.elementType == "ls") {
			this.editLesson();
		}
		else if (this.ctx.elementType == "pl") {
			if (this.options.readOnly || this.ctx.readOnly) {
				alert(language.Generic.Curriculum.kErrMsgCantViewPlan);
			} else {
				alert(language.Generic.Curriculum.kErrMsgCantEditPlan);
			}
		} else {
			alert(language.Generic.Curriculum.kErrMsgYouNeedSelectUnitOrLessonFirst);
		}
	}

	editUnit() {
		var form = document.Planner;
		form.PLANID.value = this.ctx.planId;
		form.UNID.value = this.ctx.elementId;
		form.RO.value = (this.ctx.readOnly ? "1" : "0");
		DoSubmit( form, 'EditUnit.asp' );
	}

	editLesson() {
		var currGrade = $("[name='GRADEID']").val();
		var form = document.Planner;
		form.LSID.value = this.ctx.elementId;
		form.UNID.value = this.ctx.unitId;
		form.PLANID.value = this.ctx.planId;
		form.GRADEID.value = currGrade;
		form.RO.value = (this.ctx.readOnly ? "1" : "0");
		DoSubmit( form, 'EditLesson.asp' );
	}

	copyItem() {
		if (this.ctx.elementType == "un")
			this.copyUnit();
		else if (this.ctx.elementType == "ls")
			this.copyLesson();
		else if (this.ctx.elementType == "pl")
			alert(language.Generic.Curriculum.kErrMsgCantCopyPlan);
		else alert(language.Generic.Curriculum.kErrMsgYouNeedSelectUnitOrLessonFirst);
	}

	copyUnit() {
		var form = document.Planner;
		form.PLANID.value = this.ctx.planId;
		form.UNID.value = this.ctx.elementId;
		DoSubmit( form, 'CopyUnit.asp' );
	}

	copyLesson() {
		var form = document.Planner;
		form.LSID.value = this.ctx.elementId;
		form.UNID.value = this.ctx.unitId;
		form.PLANID.value = this.ctx.planId;
		DoSubmit( form, 'CopyLesson.asp' );
	}

	createItem() {
		if (this.ctx.elementType == "pl")
			this.createUnit();
		else if (this.ctx.elementType == "un")
			this.createLesson();
		else
			alert(language.Generic.Curriculum.kErrMsgYouNeedSelectPlanOrUnitFirst);
	}

	deleteItem() {
		if (this.ctx.elementType == "un")
			this.deleteUnit();
		else if (this.ctx.elementType == "ls")
			this.deleteLesson();
		else if (this.ctx.elementType == "pl")
			alert(language.Generic.Curriculum.kErrMsgCantDeletePlan);
		else alert(language.Generic.Curriculum.kErrMsgYouNeedSelectUnitOrLessonFirst);
	}

	createUnit() {
		var form = document.Planner;
		form.PLANID.value = this.ctx.elementId;
		form.UNID.value = -1;
		form.RO.value = (this.ctx.readOnly ? "1" : "0");

		DoSubmit( form, 'EditUnit.asp' );
	}

	createLesson() {
		var currGrade = $("[name='GRADEID']").val();
		var form = document.Planner;
		form.LSID.value = -1;
		form.UNID.value = this.ctx.elementId;
		form.PLANID.value = this.ctx.planId;
		form.GRADEID.value = currGrade;
		form.RO.value = (this.ctx.readOnly ? "1" : "0");

		DoSubmit( form, 'EditLesson.asp' );
	}

	deleteUnit() {
		$.show.confirmation(language.Generic.Curriculum.kMsgDeletingUnit).then(() => {
			var url = urlHelper.makeUrl('/webapi/subjectplans/units',
				{
					unitId: this.ctx.elementId,
					planId: this.ctx.planId
				});

			jsSubmit({ method: "DELETE", action: url, showProcessing: true, auth: false }).then(() => this.load());
		});
	}

	deleteLesson() {
		$.show.confirmation(language.Generic.Common.kMsgAreYouSure).then(() => {
			var url = urlHelper.makeUrl('/webapi/subjectplans/lessons',
				{
					lessonId: this.ctx.elementId,
					unitId: this.ctx.unitId,
					planId: this.ctx.planId
				});

			jsSubmit({ method: "DELETE", action: url, showProcessing: true, auth: false }).then(() => this.load());
		});
	}

	exportKTP() {
		if (this.ctx.elementType != "pl") {
			alert(language.Generic.Curriculum.kForExportSelectVariantWithUnit);
			return;
		}

		$.show.confirmation(language.Generic.Curriculum.kExportVariantConfirm.replace("%", "<b>" + this.ctx.currElementName + "</b>"))
			.then(() => {
			postTo({
				path: "/webapi/subjectplans/export",
				formParams: { method: "GET" },
				params: {
					PLANID: this.ctx.elementId
				}
			});
		});
	}

	importKTP() {
		if (this.ctx.elementType != "pl" || this.ctx.elementId == "0") {
			alert(language.Generic.Curriculum.kForImportSelectEmptyVariant);
			return;
		}

		const plan = this.getPlan();

		if (plan.isFolder) {
			alert(language.Generic.Curriculum.kForImportSelectEmptyVariant);
			return;
		}

		var fpVals = this.fp.getValues();

		$.show.fileDialog({
			title: language.Generic.Curriculum.kImportVariant,
			fileExts: ['.xls'],
			submitParams: { SJID: fpVals.SBJID, GRADEID: fpVals.GRADEID, PlanID: this.ctx.elementId },
			url: '/asp/Curriculum/PlannerImportSave.asp'
		});

	}

	openReport() {
		if (!this.ctx.planId) {
			alert(language.Generic.Curriculum.kErrMsgYouNeedSelectPlanFirst);
			return;
		}
		const plan = this.getPlan();
		if (!plan.isFolder) {
			alert(language.Generic.Curriculum.kEmptyPlanUnits);
			return;
		}

		const reportTypes = [
			{ id: 0, name: language.Generic.Curriculum.kReducedPlan },
			{ id: 1, name: language.Generic.Curriculum.kReducedPlan_withHA },
			{ id: 2, name: language.Generic.Curriculum.kFullPlan }
		];

		if (this.options.moduleQa) {
			reportTypes.push({ id: 3, name: language.Generic.Curriculum.kFullPlan_withDecKES });
		}

		const dialogContent = "<form name=\"form\">" +
			"<div class=\"form-group\">" +
				"<select class=\"form-control\" name=\"reportType\"></select>" +
			"</div>" +
			"</form>";

		let selectRepType;
		$.show.dialog({
			title: "Выберите вид отчета",
			message: dialogContent,
			onshow: (dialog) => {
				selectRepType = $(dialog.$modalBody).find("select");
				_.each(reportTypes, (reportType) => {
					selectRepType.append($("<option></option>")
						.attr("value", reportType.id)
						.text(reportType.name));
				});
			},
			buttons:[
				{
					label: language.Generic.Buttons.kPrint,
					
					action: () => {
						const reportType = selectRepType.val();
						window.schowParams = getReportParams("Print");
						schowParams.additionalParams = { 'PLANID': this.ctx.planId, 'kViewReport': reportType };
						window.ShowReport(schowParams);
					},
					cssClass: 'btn-primary'
				},
				{
					label: language.Generic.Buttons.kExport,

					action: () => {
						const reportType = selectRepType.val();
						window.schowParams = getReportParams("Excel");
						schowParams.additionalParams = { 'PLANID': this.ctx.planId, 'kViewReport': reportType };
						window.ShowReport(schowParams);
					},
					cssClass: 'btn-primary'
				}
			]	
		});

		
		
	}

	goVariants() {
		DoSubmit(document.FilterForm, 'VariantsEdit.asp');
	}

	expandAll() {
		this.load({ expandAll: true });
	}

	collapseAll() {
		var recFunc = (node) => {
			node.expand(false);
			node.visit(recFunc);
		};
		this.options.container.dynatree("getRoot").visit(recFunc);
	}
}

module.exports = PlannerCtrl;

	


